#!/usr/bin/env node
/**
 * gen-locked-vocab.mjs
 *
 * Cycle 1.5 — Generates the "## 부록 A: 도메인 예시" section in the 4 cycle-1.5
 * SKILL.md files (investigate, retro, security-review, code-review) from the
 * single-source-of-truth: policies/locked-vocab.json.
 *
 * Scope: ONLY the cycle-1.5 4 SKILLs. The other 69 SKILLs use cycle3-body-neutral
 * marker (cycle 3/5 conversion) OR `grandfathered: true` frontmatter; their
 * appendices are NOT auto-generated by this script.
 *
 * Usage:
 *   node scripts/gen-locked-vocab.mjs           # regenerate appendix in cycle-1.5 4 SKILLs
 *   node scripts/gen-locked-vocab.mjs --check   # exit 1 if appendix is out of sync
 *
 * Idempotent: re-running with same SoT produces identical SKILL.md content.
 *
 * Why: D-4 (d). Manual multi-file editing of locked vocabulary is error-prone.
 *      One SoT file regenerates cycle-1.5 SKILL appendices — eliminates drift (위-9).
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const SOT_PATH = path.join(ROOT, 'policies/locked-vocab.json');
const SKILLS = ['investigate', 'retro', 'security-review', 'code-review'];

const APPENDIX_BEGIN = '<!-- BEGIN: locked-vocab-appendix (auto-generated by scripts/gen-locked-vocab.mjs) -->';
const APPENDIX_END = '<!-- END: locked-vocab-appendix -->';

function loadSoT() {
  const raw = fs.readFileSync(SOT_PATH, 'utf8');
  const sot = JSON.parse(raw);
  if (!['1.0', '1.1'].includes(sot.version)) {
    throw new Error(`SoT version mismatch: expected "1.0" or "1.1", got "${sot.version}"`);
  }
  if (!Array.isArray(sot.vocabs) || sot.vocabs.length !== 20) {
    throw new Error(`SoT vocabs must be exactly 20 entries, got ${sot.vocabs?.length}`);
  }
  return sot;
}

function renderVocabTable(sot, domain) {
  const rows = sot.vocabs
    .filter((v) => v.domain === domain)
    .map((v) => `| \`${v.term}\` | ${v.meaning} |`)
    .join('\n');
  return `| 어휘 | 의미 |\n|------|------|\n${rows}`;
}

function renderDomainSection(sot, domain, skill, label) {
  const ex = sot.domain_examples?.[domain]?.[skill];
  if (!ex) return '';
  let body = `### A.${label} ${domain.toUpperCase()} 예시\n\n#### 잠금 어휘 (${domain})\n\n${renderVocabTable(sot, domain)}\n\n#### 시나리오\n\n**${ex.title}**\n\n`;
  if (ex.scenario) body += `> ${ex.scenario}\n\n`;
  if (ex.options) {
    body += '| 선택지 | ✅ 좋은 점 | ❌ 나쁜 점 |\n|---|---|---|\n';
    for (const opt of ex.options) {
      body += `| ${opt.label} | ${opt.pros.map((p) => `✅ ${p}`).join('<br>')} | ${opt.cons.map((c) => `❌ ${c}`).join('<br>')} |\n`;
    }
    body += '\n';
  }
  if (ex.recommendation) body += `**추천**: ${ex.recommendation}\n\n`;
  if (ex.summary) body += `**요약**: ${ex.summary}\n\n`;
  if (ex.verdict) body += `**판정**: ${ex.verdict}\n\n`;
  if (ex.finding) body += `**발견**: ${ex.finding}\n\n`;
  return body;
}

function renderAppendix(sot, skillKey) {
  const sections = [
    renderDomainSection(sot, 'mcu', skillKey, '1'),
    renderDomainSection(sot, 'mpu', skillKey, '2'),
    renderDomainSection(sot, 'wpf', skillKey, '3'),
  ].filter(Boolean);

  return [
    APPENDIX_BEGIN,
    '',
    '## 부록 A: 도메인 예시',
    '',
    '> 이 부록은 `scripts/gen-locked-vocab.mjs`가 `policies/locked-vocab.json` SoT에서 자동 생성합니다.',
    '> 직접 편집하지 마세요 — `bun run gen:vocab` 또는 `node scripts/gen-locked-vocab.mjs`로 재생성됩니다.',
    '',
    ...sections,
    APPENDIX_END,
    '',
  ].join('\n');
}

function skillKey(skill) {
  return skill === 'security-review' ? 'security_review' : skill === 'code-review' ? 'code_review' : skill;
}

function applyToSkill(sot, skill) {
  const skillPath = path.join(ROOT, 'skills', skill, 'SKILL.md');
  const original = fs.readFileSync(skillPath, 'utf8');
  const newAppendix = renderAppendix(sot, skillKey(skill));

  let updated;
  const beginIdx = original.indexOf(APPENDIX_BEGIN);
  const endIdx = original.indexOf(APPENDIX_END);
  if (beginIdx >= 0 && endIdx > beginIdx) {
    updated = original.slice(0, beginIdx) + newAppendix + original.slice(endIdx + APPENDIX_END.length + 1);
  } else {
    const trimmed = original.replace(/\s+$/, '');
    updated = trimmed + '\n\n---\n\n' + newAppendix;
  }
  return { skillPath, original, updated };
}

const checkOnly = process.argv.includes('--check');
const sot = loadSoT();
let changed = 0;
let drift = 0;

for (const skill of SKILLS) {
  const { skillPath, original, updated } = applyToSkill(sot, skill);
  if (original === updated) continue;
  if (checkOnly) {
    console.error(`❌ DRIFT: ${path.relative(ROOT, skillPath)} appendix out of sync with SoT`);
    drift++;
  } else {
    fs.writeFileSync(skillPath, updated, 'utf8');
    console.log(`✅ updated: ${path.relative(ROOT, skillPath)}`);
    changed++;
  }
}

if (checkOnly) {
  if (drift > 0) {
    console.error(`\n${drift} SKILL.md file(s) out of sync. Run: node scripts/gen-locked-vocab.mjs`);
    process.exit(1);
  }
  console.log('✅ All 4 SKILL.md appendices in sync with SoT');
} else if (changed === 0) {
  console.log('✅ No changes (appendices already in sync with SoT)');
} else {
  console.log(`\n✅ Regenerated ${changed} SKILL.md appendix section(s) from SoT`);
}
